package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for {@link MathUtils#binomialCoefficient(int, int)}.
 * Designed to maximize branch and line coverage.
 */
public class MathUtils_binomialCoefficient_TriageGen3Test {

    @Test
    public void testBinomialCoefficient_BaseCases() {
        // Case: n == k
        assertEquals("n == k should return 1", 1L, MathUtils.binomialCoefficient(5, 5));
        // Case: k == 0
        assertEquals("k == 0 should return 1", 1L, MathUtils.binomialCoefficient(5, 0));
        // Case: k == 1
        assertEquals("k == 1 should return n", 5L, MathUtils.binomialCoefficient(5, 1));
        // Case: k == n - 1
        assertEquals("k == n - 1 should return n", 5L, MathUtils.binomialCoefficient(5, 4));
    }

    @Test
    public void testBinomialCoefficient_StandardValues() {
        // Standard calculation: 5 choose 2 = 10
        assertEquals(10L, MathUtils.binomialCoefficient(5, 2));
        // Standard calculation: 10 choose 3 = 120
        assertEquals(120L, MathUtils.binomialCoefficient(10, 3));
        // Standard calculation: 10 choose 7 = 120
        assertEquals(120L, MathUtils.binomialCoefficient(10, 7));
    }

    @Test
    public void testBinomialCoefficient_LargeValues() {
        // Testing values that might trigger the binomialCoefficientDouble path
        // 30 choose 15 = 155117520
        assertEquals(155117520L, MathUtils.binomialCoefficient(30, 15));

        // 60 choose 30 is a large number but fits in long
        // 118264581564861424L
        assertEquals(118264581564861424L, MathUtils.binomialCoefficient(60, 30));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testBinomialCoefficient_NLessThanK() {
        // Should throw IllegalArgumentException: must have n >= k
        MathUtils.binomialCoefficient(5, 6);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testBinomialCoefficient_NNegative() {
        // Should throw IllegalArgumentException: must have n >= 0
        MathUtils.binomialCoefficient(-1, 0);
    }

    /**
     * This test attempts to trigger the ArithmeticException.
     * Since the implementation uses Math.round(binomialCoefficientDouble(n, k)),
     * we need values where the result is extremely high.
     */
    @Test(expected = ArithmeticException.class)
    public void testBinomialCoefficient_Overflow() {
        // Picking very large n to force the double result to be near Long.MAX_VALUE or infinity
        // Note: Actual behavior depends on binomialCoefficientDouble implementation.
        // If binomialCoefficientDouble returns a value that rounds to Long.MAX_VALUE, it throws.
        // If it's higher than Long.MAX_VALUE, Math.round might return Long.MAX_VALUE.
        MathUtils.binomialCoefficient(2000, 1000);
    }
}
